//! Canonical fieldset identity and readonly form/type metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset name=group><legend>Group<input id=exempt value=first></legend><input id=ordinary value=seed><legend><input id=later value=later></legend><fieldset id=nested><input id=nested_input value=nested></fieldset></fieldset></form><form id=other></form><fieldset id=external form=other></fieldset></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn fieldset_disabled_canonical_boolean_reflection_and_no_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'disabled'),calls=0;if(!a||typeof a.get!=='function'||typeof a.set!=='function'||a.get.name!=='get disabled'||a.set.name!=='set disabled'||a.get.length!==0||a.set.length!==1||!a.enumerable||!a.configurable||Object.hasOwn(x,'disabled'))throw 'canonical boolean descriptor';if(x.disabled!==false)throw 'absent false';a.set.call(x,{valueOf:function(){calls++;return 0;},toString:function(){calls++;return '';}});if(calls||x.disabled!==true||x.getAttribute('disabled')!=='')throw 'boolean no author conversion';x.disabled=0;if(x.disabled!==false||x.hasAttribute('disabled'))throw 'false removes';x.setAttribute('disabled','false');if(x.disabled!==true)throw 'presence not spelling';a.set.call(x);if(x.disabled!==false)throw 'missing argument false';"#);}
#[test]
fn fieldset_disabled_inert_namespace_clone_and_own_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',outer=doc.createElementNS(html,'fieldset'),x=doc.createElementNS(html,'x:fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'disabled');if(!a)throw 'canonical boolean descriptor';outer.appendChild(x);outer.disabled=true;x.setAttributeNS('urn:foreign','p:disabled','');x.setAttributeNS(null,'DISABLED','');if(x.disabled!==false)throw 'own exact attribute only';x.disabled=Symbol('truthy');if(!x.disabled||x.cloneNode(false).disabled!==true)throw 'boolean Symbol and clone';var other=new Document();if(other.adoptNode(x)!==x||x.disabled!==true)throw 'adoption identity';x.disabled=null;if(x.disabled!==false||x.getAttributeNS('urn:foreign','disabled')!=='')throw 'null false without foreign effect';"#);}
#[test]
fn fieldset_disabled_native_first_legend_and_descendant_refresh(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'disabled');if(!a)throw 'canonical boolean descriptor';x.disabled=true;if(x.disabled!==true)throw 'actual disabled presence';"#);let control=(0..d.nodes.len()).find(|&n|d.attr(n,"value")==Some("seed")).unwrap();assert!(f.controls[&control].disabled);p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('fieldset').disabled=false;");assert!(!f.controls[&control].disabled);}

#[test]
fn fieldset_disabled_nested_native_first_legend_and_own_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),nested=document.getElementById('nested');x.disabled=true;if(!x.disabled||nested.disabled!==false)throw 'own presence not effective ancestor';"#);let lookup=|name:&str|(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(name)).unwrap();let first=lookup("exempt");let ordinary=lookup("ordinary");let later=lookup("later");let nested=lookup("nested_input");assert!(!f.controls[&first].disabled);for n in [ordinary,later,nested]{assert!(f.controls[&n].disabled);}p.begin_job();run(&mut d,&mut f,&mut p,"nested.disabled=true;x.disabled=false;if(x.disabled||!nested.disabled)throw 'independent nested own attribute';");assert!(!f.controls[&ordinary].disabled);assert!(!f.controls[&later].disabled);assert!(f.controls[&nested].disabled);p.begin_job();run(&mut d,&mut f,&mut p,"nested.disabled=false;");assert!(!f.controls[&nested].disabled);}
#[test]
fn fieldset_disabled_descriptors_brands_author_overrides_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),P=HTMLFieldSetElement.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('input'),document.createElementNS('urn:foreign','fieldset'),new Document().createElementNS('http://www.w3.org/1999/xhtml','FIELDSET')]){for(var read of [a.get,a.set]){var caught=false;try{read.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine fieldset brand';}}if(calls)throw 'brand before any conversion';x.setAttribute('disabled','false');var attr=x.getAttributeNode('disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,true);var records=watch.takeRecords();if(attr!==x.getAttributeNode('disabled')||attr.value!==''||records.length!==1||records[0].oldValue!=='false'||records[0].attributeName!=='disabled')throw 'current actual Attr observation';x.disabled=false;records=watch.takeRecords();if(attr.ownerElement!==null||attr.value!==''||records.length!==1||records[0].oldValue!==''||x.hasAttribute('disabled'))throw 'actual attribute removal';Object.defineProperty(x,'disabled',{value:'author',configurable:true});a.set.call(x,true);if(x.disabled!=='author'||a.get.call(x)!==true)throw 'own shadow authority';delete x.disabled;Object.defineProperty(P,'disabled',{value:'prototype',configurable:true});if(x.disabled!=='prototype'||a.get.call(x)!==true)throw 'prototype override';delete P.disabled;if(x.disabled!==undefined||!a.get.call(x))throw 'deleted native descriptor';Object.defineProperty(P,'disabled',a);if(x.disabled!==true||Object.hasOwn(x,'disabled'))throw 'restored descriptor';"#);}
#[test]
fn fieldset_disabled_writer_refusals_preserve_native_forms_and_recover(){for inert in [false,true]{for expression in ["x.disabled=true;","a.set.call(x,true);"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});"}else{"var x=document.getElementById('fieldset'),a=Object.getOwnPropertyDescriptor(HTMLFieldSetElement.prototype,'disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let controls=format!("{:?}",f.controls.iter().map(|(&n,c)|(n,c.owner,c.disabled,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.checked)).collect::<Vec<_>>());let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(format!("{:?}",f.controls.iter().map(|(&n,c)|(n,c.owner,c.disabled,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.checked)).collect::<Vec<_>>()),controls);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.disabled!==false||watch.takeRecords().length)throw 'atomic refused boolean write';x.disabled=true;if(!a.get.call(x)||watch.takeRecords().length!==1)throw 'fresh boolean recovery';");}}}}
#[test]
fn fieldset_disabled_presence_reads_pay_names_without_copying_values(){for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','fieldset');x.setAttribute('disabled','long value');"}else{"var x=document.getElementById('fieldset');x.setAttribute('disabled','long value');"});let id=if inert{let Value::Host(id)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};id}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("fieldset")).unwrap())};let strings=p.state.limits.host.string_bytes;let limit=p.state.retained_limit;let before=(p.state.retained,p.state.dom_commits);p.begin_job();p.state.copy_work=0;p.state.limits.host.string_bytes=0;p.state.retained_limit=p.state.retained;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_get(id,script_fieldset::DISABLED_GET),Ok(Value::Bool(true))));assert_eq!((p.state.retained,p.state.dom_commits),before);p.state.limits.host.string_bytes=strings;p.state.retained_limit=limit;for deadline in [false,true]{p.begin_job();if deadline{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.fieldset_get(id,script_fieldset::DISABLED_GET).is_err());assert_eq!((p.state.retained,p.state.dom_commits),before);p.state.execution_deadline=None;}p.begin_job();run(&mut d,&mut f,&mut p,"if(!x.disabled)throw 'fresh boolean read';x.disabled=false;if(x.disabled)throw 'fresh boolean removal';");}}

#[test]
fn fieldset_disabled_saved_child_origin_blocks_mutation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('fieldset'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFieldSetElement.prototype,'disabled');a.set.call(x,true);if(a.get.call(x)!==true)throw 'captured same-origin reflection';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://foreign-fieldset-disabled.test/",&crate::navigation::Location::home()).unwrap());for expression in ["a.set.call(x,false);","a.get.call(x);"]{p.begin_job();let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);}p.set_location(&crate::navigation::address("https://fieldset-metadata.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"a.set.call(x,false);if(a.get.call(x)!==false)throw 'fresh captured reflection recovery';");}
